macro_rules! reserved_root_namespaces {
    ($( $constant_name:ident => $namespace:literal, )+) => {
        $(pub const $constant_name: &str = $namespace;)+
        pub const RESERVED_ROOT_NAMESPACES: &[&str] = &[$($constant_name),+];
    };
}

